head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > showSortableImage]<br/>sortable=true 인 Header Column 에 정렬 상태 아이콘을 항상 표시할지 설정합니다.",
    "validation" : [
        "showSortableImage=true 면 sortable=true 인 정렬 가능한 Header Column 에 정렬 상태 아이콘을 항상 표시해야 합니다.",
        "showSortableImage=false(기본값)면 정렬이 적용된 Header Column 에만 정렬 상태 아이콘을 표시하고, 미정렬 상태의 Header Column 에는 정렬 상태 아이콘을 표시하지 않아야 합니다.",
        "accessibility=true 또는 sortHeaderDiv=true 이면 항상 true 로 동작해야 합니다.",
        "sortable=true 인 Header Column 의 th 요소에 aria-sort 속성이 정렬 상태에 따라 'other', 'ascending', 'descending' 으로 설정되어야 합니다.",
        "정렬 상태 아이콘은 'w2grid_head_sort_asc', 'w2grid_head_sort_desc', 'w2grid_head_sort_none', 'w2grid_head_sort_image_none', 'w2grid_head_sortable' CSS 클래스로 적용되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 속성별 con_ selectbox 로 각각 독립 설정 (공통 gdl_boolean 바인딩 → value 1/2/3 가 아닌 getText() 로 label('' / 'true' / 'false') 판단)
    //  - con_showSortableImage : '' 미설정(기본 false) / 'true' / 'false'
    //  - con_accessibility     : '' 미설정 / 'true' (showSortableImage 강제 true 동작 검증)
    //  - con_sortHeaderDiv     : '' 미설정 / 'true' (showSortableImage 강제 true 동작 검증)
    let vShow = con_showSortableImage.getText();
    let vAccess = con_accessibility.getText();
    let vSortDiv = con_sortHeaderDiv.getText();

    // sortable=true 인 정렬 가능한 Header Column 이어야 정렬 아이콘이 의미를 가지므로 항상 sortable: true 포함
    let properties = {
        sortable: true,
        dataList: "data:dlt_bind",
    };

    // showSortableImage : 미설정('') 이면 속성 자체를 추가하지 않음(기본 false)
    if (vShow === 'true') {
        properties.showSortableImage = true;
    } else if (vShow === 'false') {
        properties.showSortableImage = false;
    }
    if (vAccess === 'true') {
        properties.accessibility = true;
    }
    if (vSortDiv === 'true') {
        properties.sortHeaderDiv = true;
    }

    let lblDesc = 'showSortableImage=' + (vShow === '' ? '(미설정)' : vShow)
        + (vAccess === 'true' ? ', accessibility=true' : '')
        + (vSortDiv === 'true' ? ', sortHeaderDiv=true' : '');

    let cList = $c.gcm.createCList(properties);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="sortable=true, ' + lblDesc + '"', '', 'label1');

    // dataList 생성 (4행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, '');
}



// 정렬 상태/아이콘 확인 : 각 sortable Header th 의 aria-sort 속성과 정렬 아이콘 CSS 클래스(w2grid_head_sort_*) 표시 여부를 출력
//  - 정렬 자체는 사용자가 헤더를 클릭하여 수행 (정렬 트리거 버튼은 생성하지 않음)
scwin.btn_checkSortState_onclick = function (e) {
    let headTable = document.querySelector("[id*='target1_head_table']");
    if (!headTable) {
        wf_body_bottom.getObj("scwin").setReturnValue("head_table 를 찾을 수 없습니다.");
        return;
    }

    // sortable=true 인 Header Column 의 th (w2grid_head_sortable 클래스 보유)
    let sortableThs = headTable.querySelectorAll("th.w2grid_head_sortable");
    if (sortableThs.length === 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("sortable Header Column(th.w2grid_head_sortable) 이 없습니다.");
        return;
    }

    wf_body_bottom.getObj("scwin").setReturnValue("[옵션] showSortableImage : " + target1.options.showSortableImage + " / accessibility : " + target1.options.accessibility + " / sortHeaderDiv : " + target1.options.sortHeaderDiv);

    for (let i = 0; i < sortableThs.length; i++) {
        let th = sortableThs[i];

        // aria-sort 속성 (@spec2) : other / ascending / descending
        let ariaSort = th.getAttribute("aria-sort");

        // 적용된 정렬 상태 아이콘 CSS 클래스 (@spec3) 수집
        //  - 기본 모드 : w2grid_head_sort_asc / _desc / _none / _image_none
        //  - sortHeaderDiv=true : ..._btn (button 렌더링), accessibility=true : ..._btn_accessibility
        //  - th 자체의 w2grid_head_sortable 도 정렬 가능 표시 클래스로 함께 확인
        //  th.outerHTML 전체에서 w2grid_head_sort* 클래스를 모두 수집 (모드별 button/div 변형 포함)
        let sortClassRegex = /w2grid_head_sort\w*/g;
        let found = (th.outerHTML.match(sortClassRegex) || []);
        found = found.filter((v, idx) => found.indexOf(v) === idx);

        // 정렬 상태 아이콘 클래스(asc/desc/none/image_none) 중 image_none 이 아닌 것이 있으면 아이콘 표시
        let iconStateClasses = found.filter(c => /sort_(asc|desc|none|image_none)/.test(c));
        let hasIcon = iconStateClasses.some(c => !/image_none/.test(c));
        let iconClassStr = found.length > 0 ? found.join(", ") : "(없음)";

        wf_body_bottom.getObj("scwin").setReturnValue("Header[" + i + "] aria-sort : " + ariaSort + " / 정렬아이콘 표시 : " + hasIcon + " / 아이콘 클래스 : " + iconClassStr);
    }
}
